window.openGlobalGenerateInvoiceModal = async function (data, onSaveSuccess = null) {
    window.ensureBillingModalsInDom();
    const genModal = document.getElementById('generate-invoice-modal');
    const lineItemsBody = document.getElementById('line-items-body');
    if (!genModal || !lineItemsBody) return;

    // Load CPT charge master list if not loaded
    let allCptMaster = [];
    try {
        const resCpt = await ApiService.request('/api/billing/cpt-codes');
        if (resCpt && resCpt.status === 'success' && Array.isArray(resCpt.data)) {
            allCptMaster = resCpt.data;
        }
    } catch (e) { }

    const fmtMoney = (n) => '$' + (parseFloat(n) || 0).toFixed(2);

    const recalcModalTotals = () => {
        let subtotal = 0;
        lineItemsBody.querySelectorAll('.line-item-row').forEach(tr => {
            const qty = parseFloat(tr.querySelector('.li-qty')?.value || 1);
            const price = parseFloat(tr.querySelector('.li-price')?.value || 0);
            const total = qty * price;
            const totEl = tr.querySelector('.li-total');
            if (totEl) totEl.textContent = fmtMoney(total);
            subtotal += total;
        });
        const discount = parseFloat(document.getElementById('inv-discount')?.value || 0);
        const total = Math.max(0, subtotal - discount);
        const subEl = document.getElementById('inv-subtotal');
        const discEl = document.getElementById('inv-discount-display');
        const totEl = document.getElementById('inv-total');
        if (subEl) subEl.textContent = fmtMoney(subtotal);
        if (discEl) discEl.textContent = '-' + fmtMoney(discount);
        if (totEl) totEl.textContent = fmtMoney(total);
    };

    const addModalLineItemRow = (item = {}) => {
        const rowId = 'row-' + Math.random().toString(36).substr(2, 9);
        const tr = document.createElement('tr');
        tr.className = 'line-item-row';
        tr.innerHTML = `
            <td>
                <select id="li-cpt-${rowId}" aria-label="CPT Code" class="form-control li-cpt" style="min-width:110px;">
                    <option value="${item.cpt_code || ''}">${item.cpt_code || 'Select...'}</option>
                    ${allCptMaster.map(c => `<option value="${c.cpt_code}" data-price="${c.default_charge}" data-desc="${c.description}" ${c.cpt_code === item.cpt_code ? 'selected' : ''}>${c.cpt_code}</option>`).join('')}
                </select>
            </td>
            <td><input type="text" id="li-cpt-desc-${rowId}" aria-label="CPT Description" class="form-control li-cpt-desc" value="${item.cpt_description || ''}" placeholder="Procedure" style="min-width:200px;"></td>
            <td><input type="number" id="li-qty-${rowId}" aria-label="Quantity" class="form-control li-qty" value="${item.quantity || 1}" min="1" style="width:60px;"></td>
            <td><input type="number" id="li-price-${rowId}" aria-label="Unit Price" class="form-control li-price" value="${parseFloat(item.unit_price || 0).toFixed(2)}" min="0" step="0.01" style="width:90px;"></td>
            <td class="li-total" style="font-weight:700;white-space:nowrap;">${fmtMoney(item.total_price || 0)}</td>
            <td><button type="button" id="remove-li-btn-${rowId}" aria-label="Remove Line Item" class="btn btn-danger btn-sm remove-line-btn" style="padding:4px 8px;"><i class="fas fa-trash"></i></button></td>
        `;
        lineItemsBody.appendChild(tr);

        tr.querySelector('.li-cpt').addEventListener('change', function () {
            const opt = this.options[this.selectedIndex];
            if (opt && opt.dataset.price) tr.querySelector('.li-price').value = parseFloat(opt.dataset.price).toFixed(2);
            if (opt && opt.dataset.desc) tr.querySelector('.li-cpt-desc').value = opt.dataset.desc;
            recalcModalTotals();
        });
        tr.querySelector('.li-qty').addEventListener('input', recalcModalTotals);
        tr.querySelector('.li-price').addEventListener('input', recalcModalTotals);
        tr.querySelector('.remove-line-btn').addEventListener('click', () => { tr.remove(); recalcModalTotals(); });
    };

    const renderModalLineItems = (items) => {
        if (!items || items.length === 0) {
            items = [{ cpt_code: '99213', cpt_description: 'Office or Outpatient Visit (Expanded)', quantity: 1, unit_price: 100.00, total_price: 100.00 }];
        }
        lineItemsBody.innerHTML = '';
        items.forEach(item => addModalLineItemRow(item));
        recalcModalTotals();
    };

    // Fill Modal Information
    document.getElementById('inv-patient-name').textContent = data.patientName || '';
    document.getElementById('inv-provider-name').textContent = data.provider || '';
    document.getElementById('inv-encounter-date').textContent = data.date || '';
    document.getElementById('inv-encounter-type').textContent = data.type ? (data.type.includes('EHR') ? data.type : `${data.type} EHR`) : 'Cardiology EHR';
    document.getElementById('inv-patient-id').value = data.patient || '';
    document.getElementById('inv-encounter-id').value = data.enc || '';
    document.getElementById('inv-date').value = new Date().toISOString().split('T')[0];
    const due = new Date(); due.setDate(due.getDate() + 30);
    document.getElementById('inv-due-date').value = due.toISOString().split('T')[0];
    document.getElementById('inv-discount').value = '0';
    document.getElementById('inv-notes').value = '';

    lineItemsBody.innerHTML = `<tr><td colspan="6" style="text-align:center;padding:20px;"><i class="fas fa-spinner fa-spin"></i> Loading charges from encounter CPT-4 codes...</td></tr>`;
    const genModalInstance = bootstrap.Modal.getOrCreateInstance(genModal, { backdrop: 'static', keyboard: false });
    genModalInstance.show();

    // Bind Close Buttons
    const closeBtn = document.getElementById('close-gen-invoice-btn');
    const cancelBtn = document.getElementById('cancel-gen-invoice-btn');
    const addLineBtn = document.getElementById('add-line-item-btn');
    const saveBtn = document.getElementById('save-invoice-btn');

    if (closeBtn) closeBtn.onclick = () => genModalInstance.hide();
    if (cancelBtn) cancelBtn.onclick = () => genModalInstance.hide();
    if (addLineBtn) addLineBtn.onclick = () => { addModalLineItemRow(); recalcModalTotals(); };

    document.getElementById('inv-discount')?.addEventListener('input', recalcModalTotals);

    // Save Invoice Listener
    if (saveBtn) {
        saveBtn.onclick = async () => {
            const lineItems = [];
            let valid = true;
            lineItemsBody.querySelectorAll('.line-item-row').forEach(tr => {
                const qty = parseInt(tr.querySelector('.li-qty')?.value || 1);
                const price = parseFloat(tr.querySelector('.li-price')?.value || 0);
                if (price < 0) { valid = false; return; }
                lineItems.push({
                    cpt_code: tr.querySelector('.li-cpt')?.value || '',
                    cpt_description: tr.querySelector('.li-cpt-desc')?.value || '',
                    quantity: qty,
                    unit_price: price,
                    total_price: qty * price,
                });
            });

            if (!valid || lineItems.length === 0) {
                Toast.show('Please add at least one valid line item.', 'error');
                return;
            }

            saveBtn.disabled = true;
            saveBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Creating...';

            const payload = {
                patient_id: document.getElementById('inv-patient-id').value,
                encounter_id: document.getElementById('inv-encounter-id').value || null,
                invoice_date: document.getElementById('inv-date').value,
                due_date: document.getElementById('inv-due-date').value,
                discount: parseFloat(document.getElementById('inv-discount').value || 0),
                notes: document.getElementById('inv-notes').value,
                line_items: lineItems,
            };

            try {
                const res = await ApiService.request('/api/billing/invoices', 'POST', payload);
                saveBtn.disabled = false;
                saveBtn.innerHTML = '<i class="fas fa-file-invoice"></i> Create &amp; Issue Invoice';

                if (res.status === 'success') {
                    Toast.show(`Invoice ${res.invoice_number} created successfully!`, 'success');
                    genModalInstance.hide();
                    if (typeof onSaveSuccess === 'function') {
                        await onSaveSuccess();
                    }
                } else {
                    Toast.show(res.message || 'Failed to create invoice.', 'error');
                }
            } catch (e) {
                saveBtn.disabled = false;
                saveBtn.innerHTML = '<i class="fas fa-file-invoice"></i> Create &amp; Issue Invoice';
                Toast.show('Error creating invoice.', 'error');
            }
        };
    }

    // Load Charges
    if (data.enc) {
        try {
            const res = await ApiService.request(`/api/billing/encounter/${data.enc}/charges`);
            if (res.status === 'success') {
                renderModalLineItems(res.line_items || []);
            } else {
                renderModalLineItems([]);
            }
        } catch (e) {
            renderModalLineItems([]);
        }
    } else {
        renderModalLineItems([]);
    }
};

window.openCreateInvoiceModal = async function (p, onSaveSuccess = null, encId = null) {
    if (!p) return;

    const encData = {
        patient: p.id,
        patientName: `${p.first_name || ''} ${p.last_name || ''}`.trim(),
        provider: p.assigned_provider_name || 'Dr. Primary Provider',
        date: new Date().toISOString().slice(0, 10),
        type: 'Family Medicine (Internal Medicine)',
        enc: encId || ''
    };

    if (encId) {
        try {
            const chargesRes = await ApiService.request(`/api/billing/encounter/${encId}/charges`);
            if (chargesRes && chargesRes.status === 'success' && chargesRes.encounter) {
                encData.provider = chargesRes.encounter.provider || encData.provider;
                encData.date = chargesRes.encounter.encounter_date || encData.date;
                encData.type = chargesRes.encounter.encounter_type || encData.type;
            }
        } catch (e) { }
    }

    window.openGlobalGenerateInvoiceModal(encData, onSaveSuccess);
};

window.openRecordPaymentModal = function (invId, currentBalance, onPaymentSuccess = null) {
    BsAlert.fire({
        title: `<span style="font-size:1.15rem; font-weight:800; color:#0f172a;">Record Payment</span>`,
        html: `
            <div style="text-align: left; padding: 6px; font-size: 0.9rem; color: #334155;">
                <div style="margin-bottom: 12px;">
                    <strong>Outstanding Balance:</strong> <span style="color:#dc2626; font-weight:800; font-size:1.05rem;">$${Number(currentBalance).toFixed(2)}</span>
                </div>
                <div style="margin-bottom: 14px;">
                    <label style="display: block; font-weight: 600; margin-bottom: 6px; color: #1e293b;">Payment Amount ($) <span style="color:#ef4444;">*</span></label>
                    <input type="number" step="0.01" id="record-pay-amount-input" class="form-control" value="${currentBalance}" style="width: 100%; height: 38px; font-size: 0.95rem;">
                </div>
            </div>
        `,
        width: '420px',
        showCancelButton: true,
        confirmButtonText: 'Submit Payment',
        cancelButtonText: 'Cancel',
        confirmButtonColor: '#166534',
        preConfirm: () => {
            const amt = parseFloat(document.getElementById('record-pay-amount-input').value || 0);
            if (!amt || amt <= 0) {
                BsAlert.showValidationMessage('Please enter a valid payment amount.');
                return false;
            }
            return amt;
        }
    }).then(async (res) => {
        if (res.isConfirmed && res.value) {
            try {
                const response = await ApiService.request(`/api/billing/invoice/${invId}/payment`, 'PUT', { amount: res.value });
                if (response.status === 'success') {
                    Toast.show(response.message || 'Payment recorded successfully!', 'success');
                    if (typeof onPaymentSuccess === 'function') await onPaymentSuccess();
                } else {
                    Toast.show(response.message || 'Error recording payment.', 'error');
                }
            } catch (e) {
                Toast.show('Error processing payment.', 'error');
            }
        }
    });
};

window.openNewEncounterModal = function (p, onSuccessCallback, editNote = null) {
    const todayStr = editNote ? (editNote.note_date ? editNote.note_date.substring(0, 10) : new Date().toISOString().slice(0, 10)) : new Date().toISOString().slice(0, 10);

    let currentVisitType = 'Follow Up';
    const activeSpec = sessionStorage.getItem('active_specialty') || 'Cardiology EHR';
    let currentSpecialty = editNote ? (editNote.encounter_type || activeSpec) : activeSpec;
    if (currentSpecialty.includes('Cardio')) currentSpecialty = 'Cardiology EHR';
    else if (currentSpecialty.includes('Ortho')) currentSpecialty = 'Orthopedic EHR';
    else if (currentSpecialty.includes('Derma')) currentSpecialty = 'Dermatology EHR';
    else if (currentSpecialty.includes('Neuro')) currentSpecialty = 'Neurology EHR';
    else if (currentSpecialty.includes('Onco')) currentSpecialty = 'Oncology EHR';
    else if (currentSpecialty.includes('Ophthal')) currentSpecialty = 'Ophthalmology EHR';
    else if (currentSpecialty.includes('Physical') || currentSpecialty.includes('PT')) currentSpecialty = 'Physical Therapy EHR';
    else currentSpecialty = 'Cardiology EHR';

    let currentMode = 'In Person';

    if (editNote && editNote.chief_complaint) {
        if (editNote.chief_complaint.includes('New Patient')) currentVisitType = 'New Patient';
        if (editNote.chief_complaint.includes('Phone Call')) currentMode = 'Phone Call';
    }

    const modalHtml = `
        <div style="text-align: left; padding: 6px 4px;">
            <div style="display: grid; grid-template-columns: 140px 1fr; align-items: center; gap: 12px; margin-bottom: 14px;">
                <label style="font-weight:600; font-size:0.9rem; color:#334155; text-align:right;">Encounter with <span style="color:#ef4444;">*</span></label>
                <select id="modal-enc-provider" class="form-control" style="height:36px; border-radius:4px; font-size:0.9rem;">
                    <option value="">--Loading Providers--</option>
                </select>
            </div>

            <div style="display: grid; grid-template-columns: 140px 1fr; align-items: center; gap: 12px; margin-bottom: 14px;">
                <label style="font-weight:600; font-size:0.9rem; color:#334155; text-align:right;">Date <span style="color:#ef4444;">*</span></label>
                <input type="date" id="modal-enc-date" class="form-control" style="height:36px; border-radius:4px; font-size:0.9rem;" value="${todayStr}">
            </div>

            <div style="display: grid; grid-template-columns: 140px 1fr; align-items: center; gap: 12px; margin-bottom: 14px;">
                <label style="font-weight:600; font-size:0.9rem; color:#334155; text-align:right;">Visit Type <span style="color:#ef4444;">*</span></label>
                <select id="modal-enc-visittype" class="form-control" style="height:36px; border-radius:4px; font-size:0.9rem;">
                    <option value="">--Select--</option>
                    <option value="New Patient" ${currentVisitType === 'New Patient' ? 'selected' : ''}>New Patient</option>
                    <option value="Follow Up" ${currentVisitType === 'Follow Up' ? 'selected' : ''}>Follow Up</option>
                </select>
            </div>

            <div style="display: grid; grid-template-columns: 140px 1fr; align-items: center; gap: 12px; margin-bottom: 14px;">
                <label style="font-weight:600; font-size:0.9rem; color:#334155; text-align:right;">Speciality Name <span style="color:#ef4444;">*</span></label>
                <select id="modal-enc-specialty" class="form-control" style="height:36px; border-radius:4px; font-size:0.9rem;">
                    <option value="">--Select--</option>
                    <option value="Cardiology EHR" ${currentSpecialty === 'Cardiology EHR' || currentSpecialty === 'Cardiology' ? 'selected' : ''}>Cardiology EHR</option>
                    <option value="Orthopedic EHR" ${currentSpecialty === 'Orthopedic EHR' || currentSpecialty === 'Orthopedics' ? 'selected' : ''}>Orthopedic EHR</option>
                    <option value="Dermatology EHR" ${currentSpecialty === 'Dermatology EHR' || currentSpecialty === 'Dermatology' ? 'selected' : ''}>Dermatology EHR</option>
                    <option value="Neurology EHR" ${currentSpecialty === 'Neurology EHR' || currentSpecialty === 'Neurology' ? 'selected' : ''}>Neurology EHR</option>
                    <option value="Oncology EHR" ${currentSpecialty === 'Oncology EHR' || currentSpecialty === 'Oncology' ? 'selected' : ''}>Oncology EHR</option>
                    <option value="Ophthalmology EHR" ${currentSpecialty === 'Ophthalmology EHR' || currentSpecialty === 'Ophthalmology' ? 'selected' : ''}>Ophthalmology EHR (covers optometry)</option>
                    <option value="Physical Therapy EHR" ${currentSpecialty === 'Physical Therapy EHR' || currentSpecialty === 'Physical Therapy' ? 'selected' : ''}>Physical Therapy EHR (covers chiropractic)</option>
                </select>
            </div>

            <div style="display: grid; grid-template-columns: 140px 1fr; align-items: center; gap: 12px; margin-bottom: 6px;">
                <label style="font-weight:600; font-size:0.9rem; color:#334155; text-align:right;">Encounter Mode <span style="color:#ef4444;">*</span></label>
                <div style="display: flex; gap: 20px; align-items: center;">
                    <label style="font-weight:500; font-size:0.88rem; color:#334155; cursor:pointer; display:inline-flex; align-items:center; gap:6px;">
                        <input type="radio" name="enc_mode_opt" value="In Person" ${currentMode === 'In Person' ? 'checked' : ''} style="accent-color:#0284c7;"> In Person
                    </label>
                    <label style="font-weight:500; font-size:0.88rem; color:#334155; cursor:pointer; display:inline-flex; align-items:center; gap:6px;">
                        <input type="radio" name="enc_mode_opt" value="Phone Call" ${currentMode === 'Phone Call' ? 'checked' : ''} style="accent-color:#0284c7;"> Phone Call
                    </label>
                </div>
            </div>
        </div>
    `;

    BsAlert.fire({
        title: editNote ? 'Edit Encounter' : 'New Encounter',
        html: modalHtml,
        width: '460px',
        showCancelButton: true,
        confirmButtonText: editNote ? 'Update' : 'Create',
        cancelButtonText: 'Cancel',
        confirmButtonColor: '#f97316',
        cancelButtonColor: '#e2e8f0',
        didOpen: async (mEl) => {
            const cBtn = mEl.querySelector('.swal2-cancel');
            if (cBtn) cBtn.style.color = '#334155';

            const providerSelect = mEl.querySelector('#modal-enc-provider');
            const specSelect = mEl.querySelector('#modal-enc-specialty');

            let providers = [];
            try {
                let res = await ApiService.request('/api/providers');
                if (res.status !== 'success' || !Array.isArray(res.data)) {
                    res = await ApiService.request('/api/patients/providers');
                }
                if (res.status === 'success' && Array.isArray(res.data)) {
                    providers = res.data;
                }
            } catch (e) {
                console.error('Error fetching providers', e);
            }

            const populateProviders = (selectedSpec) => {
                if (!providerSelect) return;
                providerSelect.innerHTML = '<option value="">--Select Provider--</option>';
                const filtered = providers.filter(pr => {
                    if (!selectedSpec) return true;
                    if (!pr.specialty) return true;
                    return pr.specialty.toLowerCase().includes(selectedSpec.toLowerCase()) || selectedSpec.toLowerCase().includes(pr.specialty.toLowerCase());
                });

                const listToUse = filtered.length > 0 ? filtered : providers;
                listToUse.forEach(pr => {
                    const opt = document.createElement('option');
                    opt.value = pr.id;
                    opt.textContent = `Dr. ${pr.first_name} ${pr.last_name} (${pr.role})`;
                    if (editNote && (editNote.provider_id == pr.id || editNote.signed_by_name?.includes(pr.last_name))) {
                        opt.selected = true;
                    }
                    providerSelect.appendChild(opt);
                });
            };

            populateProviders(specSelect?.value || '');
            if (specSelect) {
                specSelect.addEventListener('change', () => {
                    populateProviders(specSelect.value);
                });
            }
        },
        preConfirm: () => {
            const providerSelect = document.getElementById('modal-enc-provider');
            const providerId = providerSelect?.value;
            const providerName = providerSelect && providerSelect.selectedIndex >= 0 ? providerSelect.options[providerSelect.selectedIndex]?.text : '';
            const visitType = document.getElementById('modal-enc-visittype')?.value;
            const specialty = document.getElementById('modal-enc-specialty')?.value;
            const encDate = document.getElementById('modal-enc-date')?.value || todayStr;
            const mode = document.querySelector('input[name="enc_mode_opt"]:checked')?.value || 'In Person';

            if (!providerId) {
                BsAlert.showValidationMessage('Please select a Provider.');
                return false;
            }
            if (!visitType) {
                BsAlert.showValidationMessage('Please select a Visit Type.');
                return false;
            }
            if (!specialty) {
                BsAlert.showValidationMessage('Please select a Speciality Name.');
                return false;
            }

            let encType = specialty;
            if (specialty === 'Cardiology EHR' || specialty === 'Cardiology') encType = 'Cardiology';
            else if (specialty === 'Orthopedic EHR' || specialty === 'Orthopedics') encType = 'Orthopedics';
            else if (specialty === 'Dermatology EHR' || specialty === 'Dermatology') encType = 'Dermatology';
            else if (specialty === 'Neurology EHR' || specialty === 'Neurology') encType = 'Neurology';
            else if (specialty === 'Oncology EHR' || specialty === 'Oncology') encType = 'Oncology';
            else if (specialty.includes('Ophthalmology')) encType = 'Ophthalmology';
            else if (specialty.includes('Physical Therapy')) encType = 'Physical Therapy';

            return {
                patient_id: p ? p.id : (editNote ? editNote.patient_id : null),
                provider_id: providerId,
                encounter_type: encType,
                chief_complaint: `${visitType} - ${specialty} (${mode})`,
                note_date: encDate,
                signed_by_name: providerName,
                vital_bp_systolic: editNote?.vital_bp_systolic || 120,
                vital_bp_diastolic: editNote?.vital_bp_diastolic || 80,
                vital_heart_rate: editNote?.vital_heart_rate || 72,
                vital_temp: editNote?.vital_temp || 98.6
            };
        }
    }).then(async (result) => {
        if (result.isConfirmed && result.value) {
            let res;
            if (editNote) {
                res = await ApiService.request(`/api/clinical/notes/${editNote.id}`, 'PUT', result.value);
            } else {
                res = await ApiService.request('/api/clinical/notes', 'POST', result.value);
            }

            if (res.status === 'success') {
                Toast.show(editNote ? 'Encounter updated successfully!' : 'New clinical encounter created successfully!', 'success');
                if (typeof onSuccessCallback === 'function') onSuccessCallback(result.value);
            } else {
                Toast.show(res.message || 'Error saving encounter.', 'error');
            }
        }
    });
};

window.openGlobalViewInvoiceModal = async function (id, onPaymentSuccess = null, autoFocusPayment = false) {
    window.ensureBillingModalsInDom();
    const viewModal = document.getElementById('view-invoice-modal');
    const printArea = document.getElementById('invoice-print-area');
    if (!viewModal || !printArea) return;

    printArea.innerHTML = `<div style="text-align:center;padding:40px;"><i class="fas fa-spinner fa-spin fa-2x"></i><br>Loading invoice...</div>`;
    const viewModalInstance = bootstrap.Modal.getOrCreateInstance(viewModal, { backdrop: 'static', keyboard: false });
    viewModalInstance.show();

    const statusBadge = (s) => {
        switch (s) {
            case 'Draft': return '<span class="badge-role badge-secondary">Draft</span>';
            case 'Issued': return '<span class="badge-role badge-primary">Issued</span>';
            case 'Partially Paid': return '<span class="badge-role badge-warning">Partially Paid</span>';
            case 'Paid': return '<span class="badge-role badge-success">Paid</span>';
            case 'Overdue': return '<span class="badge-role badge-danger">Overdue</span>';
            default: return `<span class="badge-role">${s}</span>`;
        }
    };
    const fmt = (n) => '$' + parseFloat(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    const res = await ApiService.request(`/api/billing/invoice/${id}`);
    if (res.status !== 'success') { Toast.show('Failed to load invoice.', 'error'); return; }
    const inv = res.invoice;
    const items = res.line_items || [];
    const clinicName = document.querySelector('.brand-title-text')?.textContent || 'Specialty EHR';

    printArea.innerHTML = `
        <div style="padding:8px;">
            <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px;padding-bottom:16px;border-bottom:2px solid var(--border-color);">
                <div>
                    <div style="font-size:1.4rem;font-weight:800;color:var(--primary-color);">${clinicName}</div>
                    <div style="color:var(--text-secondary);font-size:0.85rem;margin-top:4px;">${document.getElementById('global-specialty-name')?.textContent || 'Clinical EHR'}</div>
                </div>
                <div style="text-align:right;">
                    <div style="font-size:1.8rem;font-weight:800;color:var(--text-primary);">INVOICE</div>
                    <div style="font-size:1rem;font-weight:700;color:var(--primary-color);">${inv.invoice_number}</div>
                    <div style="font-size:0.8rem;color:var(--text-secondary);">Date: ${inv.invoice_date} &nbsp;|&nbsp; Due: ${inv.due_date}</div>
                    <div style="margin-top:8px;">${statusBadge(inv.status)}</div>
                </div>
            </div>

            <div style="display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-bottom:24px;">
                <div style="background:var(--bg-secondary);padding:16px;border-radius:8px;">
                    <div style="font-size:0.75rem;font-weight:700;color:var(--text-secondary);text-transform:uppercase;margin-bottom:8px;">BILL TO</div>
                    <div style="font-weight:700;font-size:1rem;">${inv.patient_name}</div>
                    ${inv.patient_phone ? `<div style="color:var(--text-secondary);font-size:0.85rem;margin-top:4px;">Phone: ${inv.patient_phone}</div>` : ''}
                    ${inv.patient_dob ? `<div style="color:var(--text-secondary);font-size:0.85rem;">DOB: ${inv.patient_dob}</div>` : ''}
                </div>
                <div style="background:var(--bg-secondary);padding:16px;border-radius:8px;">
                    <div style="font-size:0.75rem;font-weight:700;color:var(--text-secondary);text-transform:uppercase;margin-bottom:8px;">SERVICE DETAILS</div>
                    <div style="font-size:0.85rem;margin-bottom:4px;"><strong>Provider:</strong> ${inv.provider_name || inv.created_by}</div>
                    <div style="font-size:0.85rem;margin-bottom:4px;"><strong>Encounter:</strong> ${inv.encounter_id ? 'ENC-' + String(inv.encounter_id).padStart(5, '0') : 'N/A'}${inv.encounter_date ? ' &nbsp;(' + String(inv.encounter_date).slice(0, 10) + ')' : ''}</div>
                    <div style="font-size:0.85rem;"><strong>Specialty:</strong> ${(document.getElementById('global-specialty-name')?.textContent || '').replace(/\s*EHR$/, '')}</div>
                </div>
            </div>

            <table style="width:100%;min-width:0;border-collapse:collapse;margin-bottom:20px;">
                <thead>
                    <tr style="background:var(--primary-color);color:white;">
                        <th style="padding:10px 12px;text-align:left;font-size:0.8rem;">CPT-4 CODE</th>
                        <th style="padding:10px 12px;text-align:left;font-size:0.8rem;">PROCEDURE DESCRIPTION</th>
                        <th style="padding:10px 12px;text-align:center;font-size:0.8rem;">QTY</th>
                        <th style="padding:10px 12px;text-align:right;font-size:0.8rem;">UNIT PRICE</th>
                        <th style="padding:10px 12px;text-align:right;font-size:0.8rem;">TOTAL</th>
                    </tr>
                </thead>
                <tbody>
                    ${items.map((item, idx) => `
                        <tr style="background:${idx % 2 === 0 ? 'white' : 'var(--bg-secondary)'};">
                            <td style="padding:10px 12px;font-size:0.85rem;font-weight:700;color:var(--primary-color);">${(item.cpt_code && item.cpt_code !== '-') ? item.cpt_code : '—'}</td>
                            <td style="padding:10px 12px;font-size:0.85rem;">${item.cpt_description || 'Outpatient Procedure'}</td>
                            <td style="padding:10px 12px;text-align:center;font-size:0.85rem;">${item.quantity}</td>
                            <td style="padding:10px 12px;text-align:right;font-size:0.85rem;">${fmt(item.unit_price)}</td>
                            <td style="padding:10px 12px;text-align:right;font-size:0.85rem;font-weight:700;">${fmt(item.total_price)}</td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>

            <div style="display:flex;justify-content:flex-end;margin-bottom:20px;">
                <div style="min-width:260px;">
                    <div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border-color);">
                        <span style="color:var(--text-secondary);">Subtotal</span>
                        <strong>${fmt(inv.subtotal)}</strong>
                    </div>
                    ${parseFloat(inv.discount) > 0 ? `
                    <div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border-color);">
                        <span style="color:var(--text-secondary);">Discount</span>
                        <strong style="color:var(--danger-color);">-${fmt(inv.discount)}</strong>
                    </div>` : ''}
                    <div style="display:flex;justify-content:space-between;padding:10px 0;background:var(--primary-light,#dbeafe);border-radius:6px;padding:10px 12px;margin-top:8px;">
                        <span style="font-weight:700;font-size:1rem;">TOTAL DUE</span>
                        <strong style="font-size:1.2rem;color:var(--primary-color);">${fmt(inv.total_amount)}</strong>
                    </div>
                    <div style="display:flex;justify-content:space-between;padding:8px 12px;">
                        <span style="color:var(--success-color);font-size:0.9rem;">Amount Paid</span>
                        <strong style="color:var(--success-color);">${fmt(inv.paid_amount)}</strong>
                    </div>
                    <div style="display:flex;justify-content:space-between;padding:8px 12px;background:${parseFloat(inv.balance) > 0 ? '#fee2e2' : '#dcfce7'};border-radius:6px;">
                        <span style="font-weight:700;">BALANCE DUE</span>
                        <strong style="color:${parseFloat(inv.balance) > 0 ? 'var(--danger-color)' : 'var(--success-color)'};">${fmt(inv.balance)}</strong>
                    </div>
                </div>
            </div>

            ${inv.notes ? `
            <div style="background:var(--bg-secondary);padding:12px 16px;border-radius:8px;margin-bottom:16px;">
                <strong style="font-size:0.8rem;color:var(--text-secondary);text-transform:uppercase;">Billing Notes</strong>
                <p style="margin:4px 0 0;font-size:0.9rem;">${inv.notes}</p>
            </div>` : ''}

            <div style="text-align:center;padding:12px;color:var(--text-secondary);font-size:0.8rem;border-top:1px solid var(--border-color);">
                Thank you for choosing ${clinicName}. Please contact us if you have any questions about this invoice.
            </div>
        </div>
    `;

    const paySection = document.getElementById('record-payment-section');
    const amtInput = document.getElementById('payment-amount-input');
    if (paySection) {
        paySection.style.display = (parseFloat(inv.balance) > 0 && autoFocusPayment) ? 'flex' : 'none';
    }
    if (amtInput) {
        amtInput.value = parseFloat(inv.balance) > 0 ? parseFloat(inv.balance).toFixed(2) : '';
        if (autoFocusPayment && parseFloat(inv.balance) > 0) {
            setTimeout(() => amtInput.focus(), 150);
        }
    }

    const closeBtn = document.getElementById('close-view-invoice-btn');
    const closeBtn2 = document.getElementById('close-view-invoice-btn2');
    const printBtn = document.getElementById('print-invoice-btn');
    const payBtn = document.getElementById('submit-payment-btn');

    if (closeBtn) closeBtn.onclick = () => viewModalInstance.hide();
    if (closeBtn2) closeBtn2.onclick = () => viewModalInstance.hide();
    if (printBtn) printBtn.onclick = () => window.print();

    if (payBtn) {
        payBtn.onclick = async () => {
            const amount = parseFloat(amtInput?.value || 0);
            if (!amount || amount <= 0) { Toast.show('Please enter a valid payment amount.', 'error'); return; }
            if (amount > parseFloat(inv.balance) + 0.001) { Toast.show(`Payment cannot exceed the balance due (${fmt(inv.balance)}).`, 'error'); return; }
            const response = await ApiService.request(`/api/billing/invoice/${id}/payment`, 'PUT', { amount });
            if (response.status === 'success') {
                Toast.show(response.message, 'success');
                window.openGlobalViewInvoiceModal(id, onPaymentSuccess, false);
                if (typeof onPaymentSuccess === 'function') await onPaymentSuccess();
            } else {
                Toast.show(response.message || 'Payment failed.', 'error');
            }
        };
    }
};

// Global Event Coordinator
window.addEventListener('moduleLoaded', async (e) => {
    const currentModule = e.detail ? e.detail.module : '';
    if (currentModule) {
        await setupModuleHandlers(currentModule);
    }
});

// Global Delegated Click Listener for Log Out (Works across all modules & dynamic sidebar instances)
document.addEventListener('click', async (e) => {
    const logoutBtn = e.target.closest('#logout-btn');
    if (logoutBtn) {
        e.preventDefault();
        const tooltipEl = document.getElementById('floating-sidebar-tooltip');
        if (tooltipEl) {
            tooltipEl.style.display = 'none';
            tooltipEl.classList.remove('active');
        }
        try {
            const res = await ApiService.request('/api/logout', 'POST');
            if (res && res.status === 'success') {
                window.location.hash = '#login';
            }
        } catch (err) {
            window.location.hash = '#login';
        }
    }

});

