            if (document.getElementById('fm-ros-notes')) document.getElementById('fm-ros-notes').value = fmA.ros_notes || '';

            const painRadio = document.querySelector(`input[name="fm_pain_present"][value="${fmA.pain_present || 'No'}"]`);
