            if (document.getElementById('fm-pain-location')) document.getElementById('fm-pain-location').value = fmA.pain_location || '';
            if (document.getElementById('fm-pain-type')) document.getElementById('fm-pain-type').value = fmA.pain_type || 'Aching';
