            if (document.getElementById('fm-eye-date')) document.getElementById('fm-eye-date').value = fmA.eye_date || '';
            if (document.getElementById('fm-dental-date')) document.getElementById('fm-dental-date').value = fmA.dental_date || '';
            if (document.getElementById('fm-colonoscopy-date')) document.getElementById('fm-colonoscopy-date').value = fmA.colonoscopy_date || '';
