            if (document.getElementById('pc-prev-overall-health')) document.getElementById('pc-prev-overall-health').value = pcData.prev_overall_health || 'Excellent';
            if (document.getElementById('pc-prev-general-wellness')) document.getElementById('pc-prev-general-wellness').value = pcData.prev_general_wellness || 'Good';
