            if (canvas) {
                const ctx = canvas.getContext('2d');
                const img = new Image();
                img.onload = () => {
                    ctx.clearRect(0, 0, canvas.width, canvas.height);
                    ctx.drawImage(img, 0, 0);
                };
                img.src = note.signed_signature_data;
            }
            const sigDataUrl = document.getElementById('sig-data-url');
            if (sigDataUrl) sigDataUrl.value = note.signed_signature_data;

