    const loadHistory = async (patientId) => {
        const res = await ApiService.request(`/api/clinical/notes/${patientId}`);
        savedNotes = res.data || [];
        historySection.classList.remove('hidden');

        if (savedNotes.length > 0) {
            historyList.innerHTML = savedNotes.map((note, idx) => {
                const docName = `Dr. ${note.first_name} ${note.last_name}`;
                const encRef = `ENC-${String(note.id).padStart(5, '0')}`;
                const specMap = {
                    'Cardiology': 'Cardiology EHR',
                    'Orthopedics': 'Orthopedic EHR',
                    'Dermatology': 'Dermatology EHR',
                    'Neurology': 'Neurology EHR',
                    'Oncology': 'Oncology EHR',
                    'Ophthalmology': 'Ophthalmology EHR (covers optometry)',
                    'Physical Therapy': 'Physical Therapy EHR (covers chiropractic)',
                    'General': 'Family Medicine (Internal Medicine)',
                    'Pediatrics': 'Pediatrics EHR',
                    'OB/GYN': 'OB/GYN EHR'
                };
                const specialtyName = specMap[note.encounter_type] || `${note.encounter_type} EHR`;
                return `
                    <div class="card-summary-box">
                        <div>
                            <div class="d-flex-gap-8">
                                <div class="text-primary-bold-sm">Encounter #${encRef} (${note.note_date})</div>
                                <span class="badge-role badge-primary-xs">${specialtyName}</span>
                            </div>
                            <div class="text-sm-secondary-mt6">
                                Clinician: ${docName} | Vitals: <span class="text-mono-bold">${vitalsSummary}</span>
                            </div>
                        </div>
                        <div class="d-flex-gap-8-only">
                            <button class="btn btn-secondary btn-sm view-note-btn p-6-12-sm" data-idx="${idx}">View / Edit</button>
                            <button class="btn btn-primary btn-sm print-note-btn btn-success-sm" data-idx="${idx}">Print Report</button>
                        </div>
                    </div>
                `;
            }).join('');

            // Bind buttons
            historyList.querySelectorAll('.view-note-btn').forEach(btn => {
                btn.onclick = () => {
                    const idx = parseInt(btn.getAttribute('data-idx'));
                    const note = savedNotes[idx];
                    populateEncounterModal(note);
                };
            });

            historyList.querySelectorAll('.print-note-btn').forEach(btn => {
                btn.onclick = () => {
                    const idx = parseInt(btn.getAttribute('data-idx'));
                    const note = savedNotes[idx];
                    printEncounterReport(note);
                };
            });
        } else {
            historyList.innerHTML = `
                <div class="empty-state-box">
                    <div class="text-lg-primary-bold"><i class="fas fa-file-medical-alt mr-6"></i> No Previous Clinical Encounters</div>
                    <div class="text-sm">Click <strong>"+ Start New Encounter"</strong> to create this patient's first clinical SOAP note.</div>
                </div>
            `;
        }
    };

