                const rowParts = rows.map(tr => {
                    const tds = tr.querySelectorAll('td');
                    const rel = tds[0] ? (tds[0].querySelector('.fh-rel-badge') ? tds[0].querySelector('.fh-rel-badge').textContent.trim() : tds[0].textContent.trim()) : '';
                    const cond = tds[1] ? tds[1].textContent.trim() : '';
                    const date = tds[2] ? (tds[2].querySelector('em') ? '' : tds[2].textContent.trim()) : '';
                    return date ? `${rel}: ${cond} (Start: ${date})` : `${rel}: ${cond}`;
                });
                const tableStr = rowParts.join(' | ');
                if (tableStr && summary) return `${tableStr} -- ${summary}`;
